application.css:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap');

:root { --ink:#172329; --muted:#718087; --cream:#f7f5ef; --line:#e3e7e4; --teal:#1d827e; --mint:#dff1e9; --yellow:#f8c75d; }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; background:var(--cream); color:var(--ink); font-family:'DM Sans',sans-serif; }
.page-shell { max-width:850px; margin:auto; padding:58px 24px 35px; }
.hero { text-align:center; margin-bottom:35px; }
.eyebrow { color:var(--teal); font-size:11px; font-weight:700; letter-spacing:2.5px; }
h1 { font-family:'Space Grotesk',sans-serif; font-size:clamp(38px,7vw,64px); line-height:1; letter-spacing:-3px; margin:15px 0 13px; }
h1 span { color:var(--teal); }
.hero p { color:var(--muted); margin:0; font-size:15px; }
.quiz-card { background:#fff; border-radius:20px; padding:34px 42px 32px; box-shadow:0 18px 50px rgba(35,56,54,.08); }
.card-topline { display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--line); padding-bottom:22px; }
h2 { font:600 20px 'Space Grotesk',sans-serif; margin:0; }
.question-count { font-weight:700; font-size:14px; color:var(--teal); }
.question-count span { color:#a3adae; font-size:9px; letter-spacing:1px; margin-left:3px; }
.question { border:0; border-bottom:1px solid var(--line); padding:26px 0 27px; margin:0; min-width:0; }
legend { display:flex; gap:17px; align-items:flex-start; width:100%; font:600 17px 'Space Grotesk',sans-serif; }
.number { color:var(--teal); font-size:12px; letter-spacing:1px; padding-top:3px; }
.options { display:grid; grid-template-columns:repeat(3,1fr); gap:10px; margin:20px 0 0 31px; }
.option { display:flex; align-items:center; gap:10px; border:1px solid var(--line); border-radius:9px; padding:13px 12px; color:#536166; font-size:14px; cursor:pointer; transition:.2s ease; }
.option:hover { border-color:#9ccbc1; background:#f6fcf9; color:var(--ink); }
.option input { position:absolute; opacity:0; pointer-events:none; }
.radio-mark { width:16px; height:16px; flex:none; border:1.5px solid #b7c2c1; border-radius:50%; position:relative; }
.option:has(input:checked) { border-color:var(--teal); background:var(--mint); color:var(--ink); }
.option:has(input:checked) .radio-mark { border-color:var(--teal); }
.option:has(input:checked) .radio-mark:after { content:''; position:absolute; inset:3px; background:var(--teal); border-radius:50%; }
.actions { display:flex; align-items:center; justify-content:space-between; padding-top:27px; }
.status { color:#bd5c46; font-size:13px; margin:0; min-height:18px; }
button { border:0; border-radius:9px; background:var(--teal); color:#fff; padding:14px 22px; font:700 14px 'DM Sans',sans-serif; cursor:pointer; transition:.2s; }
button:hover { background:#176965; transform:translateY(-1px); }
button span { font-size:20px; vertical-align:-2px; margin-left:10px; }
.result { display:none; text-align:center; border-radius:13px; margin-top:25px; padding:20px; background:#f0f8f4; }
.result.show { display:block; }
.result-label { color:var(--teal); font-size:10px; font-weight:700; letter-spacing:2px; }
.score { font:700 48px 'Space Grotesk',sans-serif; color:var(--ink); line-height:1.1; margin-top:5px; }
.result-caption { color:var(--muted); font-size:12px; }
footer { text-align:center; color:#9aa5a4; font-size:12px; margin-top:27px; }
footer span { color:var(--yellow); margin:0 7px; }
@media (max-width:650px) { .page-shell { padding:38px 14px 25px; } .quiz-card { padding:25px 20px; } .options { grid-template-columns:1fr; margin-left:0; } .actions { align-items:flex-end; gap:10px; } }

application.javascript:
document.addEventListener('DOMContentLoaded', () => {
  const form = document.getElementById('quiz-form');
  const status = document.getElementById('status');
  const scoreEl = document.querySelector('[data-testid="quiz-score"]');
  const result = document.querySelector('.result');
  const answers = { q1: 'b', q2: 'c', q3: 'b' };

  form.addEventListener('submit', (event) => {
    event.preventDefault();
    const selected = new FormData(form);
    const unanswered = ['q1', 'q2', 'q3'].filter((name) => !selected.get(name));
    if (unanswered.length) {
      status.textContent = `Please answer ${unanswered.length === 1 ? 'the remaining question' : 'all three questions'} first.`;
      return;
    }
    status.textContent = '';
    let score = 0;
    Object.keys(answers).forEach((question) => {
      if (selected.get(question) === answers[question]) score += 1;
    });
    scoreEl.textContent = String(score);
    scoreEl.dataset.score = String(score);
    result.classList.add('show');
  });
});

